function maxOperations(s) {
  let ones = 0;
  let operations = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '1') {
      ones++;
    } else if (i > 0 && s[i - 1] === '1') {
      operations += ones;
    }
  }
  return operations;
}

