function maxOperations(s) {
  // Try every order of operations: the longest sequence from each string, memoised.
  // Every operation moves a '1' to the right, so no string can repeat and the search ends.
  const memo = new Map();
  const longest = state => {
    if (memo.has(state)) return memo.get(state);
    let best = 0;
    for (let i = 0; i + 1 < state.length; i++) {
      if (state[i] !== '1' || state[i + 1] !== '0') continue;
      let stop = i + 1;
      while (stop + 1 < state.length && state[stop + 1] === '0') stop++;
      const next = state.slice(0, i) + '0' + state.slice(i + 1, stop) + '1' + state.slice(stop + 1);
      best = Math.max(best, 1 + longest(next));
    }
    memo.set(state, best);
    return best;
  };
  return longest(s);
}

