function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 12);
  const shape = Math.floor(rand() * 4);
  if (shape === 0) {
    // A block of ones, then single zeros between single ones: close to the largest answer for this length.
    const runs = Math.floor(n / 3);
    return ['1'.repeat(n - 2 * runs) + '01'.repeat(runs)];
  }
  if (shape === 1) {
    // Alternating ones and zeros with a few flips.
    return [Array.from({ length: n }, (_, i) => ((i % 2 === 0) !== (rand() < 0.15) ? '1' : '0')).join('')];
  }
  if (shape === 2) {
    // One repeated character, sometimes with a single different one.
    const base = rand() < 0.5 ? '0' : '1';
    const chars = Array.from({ length: n }, () => base);
    if (rand() < 0.6) chars[Math.floor(rand() * n)] = base === '0' ? '1' : '0';
    return [chars.join('')];
  }
  const density = rand();
  return [Array.from({ length: n }, () => (rand() < density ? '1' : '0')).join('')];
}
